import pandas as pd
import numpy as np
from pymatgen.core import Structure

df = pd.read_csv('nlo_pool.csv')

def get_s(cid):
    row = df[df.candidate_id==cid].iloc[0]
    return Structure.from_str(row['poscar'], fmt='poscar'), row['formula']

# Te environments in c069, c079, c072, c066, c070
for cid in ['c069','c079','c072','c074','c064','c061','c089','c083','c092','c038']:
    s,f=get_s(cid)
    print(f"\n==== {cid} {f} ====")
    for el_focus in ['Te','S','Se','As','Sb','Sn','Ge','P']:
        for i,site in enumerate(s):
            if str(site.specie)!=el_focus:
                continue
            neigh=[]
            for j,site2 in enumerate(s):
                d=s.get_distance(i,j)
                cut=2.9
                if el_focus in ['Te'] or str(site2.specie) in ['Te']:
                    cut=3.2
                if el_focus in ['Sb']:
                    cut=3.1
                if 0.5<d<cut:
                    neigh.append((str(site2.specie),round(float(d),3)))
            if el_focus in ['Te','As','Sb','Sn','Ge','P'] or (el_focus in ['S','Se'] and any(x[0] in ['S','Se','Te'] for x in neigh)):
                if neigh:
                    print(f"  {el_focus}{i} {sorted(neigh,key=lambda x:x[1])[:8]}")
